// SECURE - values are BOUND as parameters, never parsed as SQL
const row = db
  .prepare("SELECT id, username, is_admin FROM users WHERE username = ? AND password = ?")
  .get(username, password);
// Defense in depth: never store plaintext passwords - hash (bcrypt/argon2), compare in constant time.

